  strings = {},
  talkScripts = {},
  text = {
    ["40:481f"] = "Crammed full of\
POKéMON books!",
    ["4e:4551_T1"] = "ROUTE_1 ",
    ["4e:4551_T2"] = "We also sell POKé BALLs!",
    ["4e:4551_TEXT"] = "",
    ["4e:45b2"] = "See those ledges\
along the road?\12It's a bit scary,\
but you can jump\11from them.\12You can get back\
to PALLET TOWN\11quicker that way.",
    ["4e:461b"] = "Hi! I work at a\
POKéMON MART.\12It's a convenient\
shop, so please\11visit us in\11VIRIDIAN CITY.\12I know, I'll give\
you a sample!\11Here!",
    ["4e:4650"] = "ROUTE 1\
PALLET TOWN -\11VIRIDIAN CITY",
    ["4e:46c2"] = "I'm raising\
POKéMON too!\12When they get\
strong, they can\11protect me!",
    ["4e:46fb"] = "Technology is\
incredible!\12You can now store\
and recall items\11and POKéMON as\11data via PC!",
    ["4e:4746"] = "PALLET TOWN\
Shades of your\11journey await!",
    ["4e:4778"] = "{PLAYER}'s house ",
    ["4e:4785"] = "OAK POKéMON\
RESEARCH LAB",
    ["4e:479c"] = "{RIVAL}'s house ",
    ["539e_T1"] = "...",
    ["5939e_T1"] = "...",
    ["59:39e_T1"] = "...",
    ["59:539e_T1"] = "All ",
    ["59:539e_T2"] = "MOM: Right.\
All boys leave\11home some day.\11It said so on TV.\12PROF.OAK, next\
door, is looking\11for you.",
    ["59:539e_TEXT"] = "...",
    ["59:547c"] = "MOM: Right. \
All boys leave \11home some day. \11It said so on TV. \12Prof. Oak, next door, is looking \11for you.",
    ["59:54e3"] = "There's a movie on TV. Four boys \11are walking on \11railroad tracks. \12I better go too",
    ["59:5922"] = "...",
    ["59:5b39e_T1"] = "...",
    ["59:5bo39e_T1"] = "...",
    ["59:5cf6"] = "I study POKéMON as\
PROF.OAK's AIDE.",
    ["59:5d54"] = "I study POKéMON as\
PROF.OAK's AIDE.",
    ["59:5da2"] = "PROF.OAK is the\
authority on\11POKéMON!\12Many POKéMON\
trainers hold him\11in high regard!",
    ["59:5de5"] = "...",
    ["59:5e04"] = "...",
    ["59:5e40"] = "...",
    ["59:5e59"] = "...",
    ["5a:40cb"] = "I'm BROCK!\
I'm PEWTER's GYM\11LEADER!\12I believe in rock\
hard defense and\11determination!\12That's why my\
POKéMON are all\11the rock-type!\12Do you still want\
to challenge me?\11Fine then! Show\11me your best!",
    ["5a:41b6"] = "I took\
you for granted.\12As proof of your\
victory, here's\11the BOULDERBADGE!\12{PLAYER} received\
the BOULDERBADGE!",
    ["5a:4252"] = "\12That's an official\
POKéMON LEAGUE\11BADGE!\12Its bearer's\
POKéMON become\11more powerful!\12The technique\
FLASH can now be\11used any time!",
    ["5a:42d5"] = "There are all\
kinds of trainers\11in the world!\12You appear to be\
very gifted as a\11POKéMON trainer!\12Go to the GYM in\
CERULEAN and test\11your abilities!",
    ["5a:435d"] = "Stop right there,\
kid!\12You're still light\
years from facing\11BROCK!",
    ["5a:43ec"] = "Darn!\12Light years isn't\
time! It measures\11distance!",
    ["5a:440a"] = "You're pretty hot,\
but not as hot\11as BROCK!",
    ["5a:4469"] = "Hiya! I can tell\
you have what it\11takes to become a\11POKéMON champ!\12I'm no trainer,\
but I can tell\11you how to win!\12Let me take you\
to the top!",
    ["5a:4502"] = "Just as I thought!\
You're POKéMON\11champ material!",
    ["5f:442e"] = "Coming up with\
nicknames is fun,\11but hard.\12Simple names are\
the easiest to\11remember.",
    ["5f:44a5"] = "My Daddy loves\
POKéMON too.",
    ["5f:44d8"] = "SPEARY: Tetweet!",
    ["5f:503e"] = "You don't have all\
the GYM BADGES of\11KANTO\12I'm sorry, but I\
can't let you go\11through.",
    ["5f:5093"] = "Oh! The eight\
BADGES of KANTO\12Please, go right\
ahead, sir!",
    All = "...",
    N = "...",
    No = "No",
    ROUTE_1 = "...",
    ["Route_!"] = "...",
    Route_1 = "...",
    T = "...",
    Well = "well",
    _PalletTownOakHeyWaitDontGoOutText = "OAK: Hey! Wait!\
Don't go out!",
    _PalletTownOakItsUnsafeText = "OAK: It's unsafe!\
Wild POKéMON live\11in tall grass!\12You need your own\
POKéMON for your\11protection.\11I know!\12Here, come with\
me!",
    ["mod:BILLS_HOUSE_GOTTA_HELP"] = "No!? Come on, you\
gotta help a guy\11in deep trouble!\12What do you say,\
chief? Please?\11OK? All right!",
    ["mod:BILLS_HOUSE_GO_INSTEAD"] = "That cruise ship,\
S.S.ANNE, is in\11VERMILION CITY.\11Its passengers\11are all trainers!\12They invited me\
